<template>
  <div class="page models-page">
    <header class="page-heading">
      <div><span class="eyebrow">MODEL CONTROL PLANE</span><h1>模型中心</h1><p>统一管理 Provider 路由、密钥引用、模型目录和运行参数；配置经 Worker 预热后才会生效。</p></div>
      <div class="heading-actions"><button class="primary-button" type="button" @click="newProvider">新建 Provider</button><button class="secondary-button" type="button" :disabled="loading" @click="load">{{ loading ? '刷新中…' : '刷新状态' }}</button></div>
    </header>

    <div v-if="error" class="notice error-notice">{{ error }}</div>
    <section class="model-metrics panel">
      <div><span>Provider</span><strong>{{ providers.length }}</strong><small>版本化路由</small></div><div><span>已生效</span><strong>{{ activeProviders }}</strong><small>完成 Worker 预热</small></div><div><span>文本模型</span><strong>{{ activeModels.filter(item => item.kind === 'llm').length }}</strong><small>可供 Agent 选择</small></div><div><span>多模态</span><strong>{{ activeModels.filter(item => item.input_modalities.some(value => value !== 'text')).length }}</strong><small>图像、音频、视频输入</small></div>
    </section>

    <nav class="model-tabs" aria-label="模型配置栏目"><button :class="{ active: tab === 'providers' }" @click="tab = 'providers'">Provider 配置</button><button :class="{ active: tab === 'catalog' }" @click="tab = 'catalog'">生效模型目录 <small>{{ activeModels.length }}</small></button><button :class="{ active: tab === 'embeddings' }" @click="tab = 'embeddings'">Embedding Profiles</button><button :class="{ active: tab === 'media' }" @click="tab = 'media'">图片与视频</button></nav>

    <EmbeddingProfiles v-if="tab === 'embeddings'" :providers="providers"/>
    <section v-else-if="tab === 'catalog'" class="panel catalog-panel">
      <div class="panel-heading"><div><span class="eyebrow">ACTIVE MODEL CATALOG</span><h2>Agent 可选模型</h2></div><router-link class="secondary-button" to="/agents">配置 Agent 模型策略 →</router-link></div>
      <div class="catalog-grid"><article v-for="model in activeModels" :key="model.model_id"><span class="model-kind">{{ kindLabel(model.kind) }}</span><h3>{{ model.name }}</h3><code>{{ model.model_id }}</code><p>{{ model.description || '未填写说明' }}</p><div><span>{{ model.input_modalities.join(' + ') }}</span><span v-if="model.context_window">{{ compactNumber(model.context_window) }} context</span><span v-if="model.max_output_tokens">{{ compactNumber(model.max_output_tokens) }} output</span></div><footer><small v-if="model.supports_tools">Tools</small><small v-if="model.supports_reasoning">Reasoning</small><small v-if="model.supports_structured_output">Structured Output</small></footer></article><div v-if="!activeModels.length" class="empty-state compact"><strong>尚无已生效模型</strong><p>创建并发布 Provider Revision 后，模型才会进入 Agent 可选目录。</p></div></div>
    </section>

    <section v-else-if="tab === 'media'" class="media-grid">
      <article class="panel media-card"><span class="media-mark">I</span><div><span class="eyebrow">IMAGE</span><h2>图片生成与编辑</h2><p>Seedream、即梦以及后续图片供应商通过 <code>image.generate</code> 和 <code>image.edit</code> Capability 配置。</p><router-link class="primary-button" to="/extensions/capability-media-generation">打开 Media Generation →</router-link></div></article>
      <article class="panel media-card"><span class="media-mark">V</span><div><span class="eyebrow">VIDEO</span><h2>视频生成</h2><p>Seedance、即梦文生视频和图生视频模型参数由 <code>video.generate</code> 的配置 Schema 管理。</p><router-link class="primary-button" to="/extensions/capability-media-generation">配置视频模型 →</router-link></div></article>
      <div class="notice media-notice"><strong>为什么不与 LLM Provider 混在一起？</strong><span>图片和视频是有成本、异步、需要审批和 Artifact 对账的 Capability；文本 LLM 是 Agent 推理 Provider。两者共享模型中心入口，但保持不同执行语义。</span></div>
    </section>

    <div v-else class="providers-layout">
      <aside class="panel provider-sidebar"><div class="panel-heading"><div><span class="eyebrow">PROVIDERS</span><h2>供应商路由</h2></div><span>{{ providers.length }}</span></div><button v-for="item in providers" :key="item.provider_id" class="provider-row" :class="{ active: selectedId === item.provider_id }" type="button" @click="selectProvider(item.provider_id)"><i :class="{ ready: item.execution_ready, configured: item.current_revision_id && !item.execution_ready }"/><span><strong>{{ item.name }}</strong><code>{{ item.provider_id }}</code><small>{{ providerState(item) }} · {{ item.model_count }} models</small></span></button><div v-if="!providers.length && !loading" class="empty-state compact"><strong>尚无 Provider 配置</strong><p>扩展负责协议实现；这里负责 Endpoint、密钥引用和模型目录。</p></div></aside>

      <main class="provider-workspace">
        <section v-if="editing" class="panel editor-panel">
          <div class="panel-heading"><div><span class="eyebrow">{{ selected ? 'NEW REVISION' : 'NEW PROVIDER' }}</span><h2>{{ selected ? `更新 ${selected.name}` : '登记模型 Provider' }}</h2></div><button class="secondary-button" type="button" @click="cancelEdit">取消</button></div>
          <form class="provider-form" @submit.prevent="saveRevision">
            <label><span>Provider ID</span><input v-model.trim="draft.provider_id" required :disabled="!!selected" placeholder="openrouter"/><small>模型 ID 必须使用该前缀，例如 openrouter/vendor/model</small></label><label><span>Provider 扩展</span><input v-model.trim="draft.extension_id" required placeholder="provider-openai-compatible"/><small>必须先在扩展中心发布生效</small></label>
            <label><span>显示名称</span><input v-model.trim="draft.name" required placeholder="OpenRouter"/></label><label><span>说明</span><input v-model.trim="draft.description" placeholder="统一模型网关"/></label>
            <label class="wide"><span>API Base</span><input v-model.trim="draft.api_base" required placeholder="https://provider.example/v1"/></label>
            <label><span>认证方式</span><select v-model="draft.credential_mode"><option value="api_key">API Key 环境引用</option><option value="none">无认证（仅本机）</option></select></label><label><span>API Key 引用</span><input v-model.trim="draft.api_key_ref" :required="draft.credential_mode === 'api_key'" :disabled="draft.credential_mode === 'none'" placeholder="env://OPENROUTER_API_KEY"/><small>只保存变量名，不保存密钥值</small></label>
            <label><span>请求超时（秒）</span><input v-model.number="draft.request_timeout_seconds" type="number" min="1" max="3600"/></label><label class="switch-field"><input v-model="draft.allow_insecure_http" type="checkbox"/><span><strong>允许本机 HTTP</strong><small>仅 localhost、127.0.0.1 和 ::1</small></span></label><label class="switch-field"><input v-model="draft.enabled" type="checkbox"/><span><strong>启用 Provider</strong><small>停用也通过新 Revision 发布</small></span></label>
            <label class="wide"><span>附加 Header 环境引用（JSON）</span><textarea v-model="headersText" rows="4" spellcheck="false" placeholder='{"X-Organization":"env://MODEL_ORG_ID"}'/><small>Header 值同样只能使用 env://VARIABLE</small></label>

            <div class="wide model-editor-heading"><div><span class="eyebrow">MODEL CATALOG</span><h3>模型与默认参数</h3></div><button class="secondary-button" type="button" @click="addModel">＋ 添加模型</button></div>
            <article v-for="(model, index) in draft.models" :key="index" class="wide model-editor-card">
              <header><strong>模型 {{ index + 1 }}</strong><button v-if="draft.models.length > 1" class="row-action danger-text" type="button" @click="removeModel(index)">移除</button></header>
              <div class="model-fields"><label class="span-2"><span>精确 Model ID</span><input v-model.trim="model.model_id" required :placeholder="`${draft.provider_id || 'provider'}/vendor/model-id`"/></label><label><span>显示名称</span><input v-model.trim="model.name" required/></label><label><span>类型</span><select v-model="model.kind"><option value="llm">文本 LLM</option><option value="embedding">Embedding</option><option value="rerank">Rerank</option><option value="transcription">语音转写</option><option value="speech">语音生成</option></select></label><label v-if="model.kind === 'embedding'"><span>Embedding Dimensions</span><input v-model.number="model.dimensions" type="number" min="1" max="16000" required/></label><label v-if="model.kind === 'embedding'"><span>每百万输入 Token 成本（USD）</span><input v-model.number="model.input_cost_per_million_tokens" type="number" min="0" step="0.000001" required/><small>本地免费模型填 0；远程模型必须明确声明。</small></label><template v-if="model.kind === 'llm'"><label><span>普通输入 / 百万 Token</span><input v-model.number="model.input_cost_per_million_tokens" type="number" min="0" step="0.000001" placeholder="留空表示未知"/></label><label><span>输出 / 百万 Token</span><input v-model.number="model.output_cost_per_million_tokens" type="number" min="0" step="0.000001" placeholder="留空表示未知"/></label><label><span>缓存读取输入 / 百万 Token</span><input v-model.number="model.cached_input_cost_per_million_tokens" type="number" min="0" step="0.000001" placeholder="不支持则留空"/></label><label><span>缓存写入输入 / 百万 Token</span><input v-model.number="model.cache_creation_input_cost_per_million_tokens" type="number" min="0" step="0.000001" placeholder="不支持则留空"/></label></template><label><span>Context Window</span><input v-model.number="model.context_window" type="number" min="0"/></label><label><span>Max Output Tokens</span><input v-model.number="model.max_output_tokens" type="number" min="0"/></label><label><span>默认 Temperature</span><input v-model.number="model.default_temperature" type="number" min="0" max="2" step="0.1"/></label><label><span>输入模态</span><input :value="model.input_modalities.join(', ')" @input="model.input_modalities = splitList(($event.target as HTMLInputElement).value)" placeholder="text, image"/></label><label class="span-2"><span>说明</span><input v-model.trim="model.description"/></label></div>
              <div class="model-switches"><label><input v-model="model.enabled" type="checkbox"/>启用</label><label><input v-model="model.supports_tools" type="checkbox"/>Tool Calling</label><label><input v-model="model.supports_reasoning" type="checkbox"/>Reasoning</label><label><input v-model="model.supports_structured_output" type="checkbox"/>Structured Output</label></div>
            </article>
            <div class="wide form-actions"><button class="primary-button" type="submit" :disabled="saving">{{ saving ? '保存中…' : '创建不可变 Draft' }}</button></div>
          </form>
        </section>

        <template v-else-if="selected">
          <section class="panel provider-hero"><div><span class="eyebrow">{{ selected.provider_id }}</span><h2>{{ selected.name }}</h2><p>{{ selected.description || '未填写说明' }}</p><code>{{ displayConfig?.api_base }}</code></div><div class="hero-actions"><button class="secondary-button" @click="editSelected">创建新 Revision</button><button v-if="publishableRevision" class="primary-button" :disabled="publishing" @click="publishProvider">{{ publishing ? '发布中…' : '发布 Provider' }}</button></div></section>
          <div v-if="selected.execution_blockers.length" class="notice blocker-notice"><strong>尚不可用于新 Agent Runtime</strong><span v-for="item in selected.execution_blockers" :key="item">{{ item }}</span></div>
          <section class="provider-detail-grid"><article class="panel"><div class="panel-heading"><div><span class="eyebrow">ACTIVE ROUTE</span><h2>运行参数</h2></div><span>{{ selected.current_revision_id || '未生效' }}</span></div><dl v-if="displayConfig"><dt>Extension</dt><dd><code>{{ displayConfig.extension_id }}</code></dd><dt>Endpoint</dt><dd><code>{{ displayConfig.api_base }}</code></dd><dt>Credential</dt><dd><code>{{ displayConfig.api_key_ref || '无认证' }}</code></dd><dt>Timeout</dt><dd>{{ displayConfig.request_timeout_seconds }} 秒</dd><dt>Worker</dt><dd>{{ selected.worker_summary.loaded }}/{{ selected.worker_summary.total }} loaded</dd></dl></article><article class="panel"><div class="panel-heading"><div><span class="eyebrow">WORKER ACK</span><h2>最近发布</h2></div><span>{{ selected.latest_rollout?.status || '无' }}</span></div><template v-if="selected.latest_rollout"><div class="progress-track"><i :style="{ width: rolloutProgress + '%' }"/></div><p class="rollout-copy">{{ selected.latest_rollout.acknowledged_worker_count }}/{{ selected.latest_rollout.target_worker_count }} Worker 已确认 · {{ selected.latest_rollout.failed_worker_count }} 失败</p><code v-for="target in selected.latest_rollout.targets" :key="target.worker_id" class="target-row">{{ target.worker_id }} · {{ target.status }} · attempt {{ target.attempt_count }}</code><button v-if="selected.latest_rollout.status === 'completed' && selected.latest_rollout.previous_revision_id" class="secondary-button danger-text rollback-button" @click="rollbackProvider">回滚到 {{ selected.latest_rollout.previous_revision_id }}</button></template><p v-else class="muted">尚未提交发布。</p></article></section>
          <section class="panel"><div class="panel-heading"><div><span class="eyebrow">MODELS</span><h2>当前模型目录</h2></div><router-link class="secondary-button" to="/agents">配置 Agent →</router-link></div><div class="active-model-list"><article v-for="model in displayConfig?.models || []" :key="model.model_id"><span class="model-kind">{{ kindLabel(model.kind) }}</span><div><strong>{{ model.name }}</strong><code>{{ model.model_id }}</code><small>{{ model.input_modalities.join(' + ') }} · temp {{ model.default_temperature }} · {{ model.supports_tools ? 'tools' : 'no tools' }}</small></div><span class="status-badge" :class="model.enabled ? 'completed' : 'cancelled'">{{ model.enabled ? '启用' : '停用' }}</span></article></div></section>
          <section class="panel"><div class="panel-heading"><div><span class="eyebrow">IMMUTABLE HISTORY</span><h2>Revision 历史</h2></div><span>{{ selected.revisions?.length || 0 }}</span></div><div class="revision-list"><article v-for="revision in selected.revisions" :key="revision.revision_id"><div><strong>v{{ revision.version }}</strong><code>{{ revision.revision_id }}</code><small>{{ formatDate(revision.created_at) }}</small></div><span class="status-badge" :class="revision.status">{{ revision.status }}</span></article></div></section>
        </template>
        <section v-else class="panel empty-workspace"><span>◌</span><strong>选择或创建一个模型 Provider</strong><p>Provider 扩展负责协议；模型中心负责版本化参数和 Worker 加载确认。</p></section>
      </main>
    </div>
  </div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useMessage } from 'naive-ui'
import { rollbackConfigurationRollout } from '../api/admin'
import { createModelProvider, createModelProviderRevision, getModelProvider, listActiveModels, listModelProviders, publishModelProviderRevision, type ModelCatalogItem, type ModelProviderProfile } from '../api/modelProviders'
import EmbeddingProfiles from '../components/EmbeddingProfiles.vue'

type Tab = 'providers' | 'catalog' | 'embeddings' | 'media'
const emptyModel = (): ModelCatalogItem => ({ model_id: '', name: '', description: '', kind: 'llm', enabled: true, input_modalities: ['text'], context_window: 0, max_output_tokens: 4096, supports_tools: true, supports_reasoning: false, supports_structured_output: true, default_temperature: 0.3, tags: [], dimensions: 0, input_cost_per_million_tokens: null, output_cost_per_million_tokens: null, cached_input_cost_per_million_tokens: null, cache_creation_input_cost_per_million_tokens: null })
const emptyDraft = () => ({ provider_id: '', name: '', description: '', enabled: true, extension_id: 'provider-openai-compatible', api_base: '', api_key_ref: '', allow_insecure_http: false, credential_mode: 'api_key', request_timeout_seconds: 120, models: [emptyModel()] })
const message = useMessage(); const tab = ref<Tab>('providers'); const loading = ref(false); const saving = ref(false); const publishing = ref(false); const error = ref(''); const providers = ref<ModelProviderProfile[]>([]); const activeModels = ref<ModelCatalogItem[]>([]); const selectedId = ref(''); const selected = ref<ModelProviderProfile | null>(null); const editing = ref(false); const draft = reactive(emptyDraft()); const headersText = ref('{}')
const activeProviders = computed(() => providers.value.filter(item => item.current_revision_id).length); const publishableRevision = computed(() => selected.value?.latest_revision?.status === 'draft' ? selected.value.latest_revision : null); const displayConfig = computed(() => selected.value?.current_revision?.configuration || selected.value?.latest_revision?.configuration || null); const rolloutProgress = computed(() => { const rollout = selected.value?.latest_rollout; return rollout?.target_worker_count ? Math.round(rollout.acknowledged_worker_count / rollout.target_worker_count * 100) : 100 })
async function load() { loading.value = true; error.value = ''; try { [providers.value, activeModels.value] = await Promise.all([listModelProviders(), listActiveModels()]); if (selectedId.value) await selectProvider(selectedId.value); else if (providers.value.length) await selectProvider(providers.value[0].provider_id) } catch (cause) { error.value = errorText(cause) } finally { loading.value = false } }
async function selectProvider(id: string) { selectedId.value = id; editing.value = false; selected.value = await getModelProvider(id) }
function newProvider() { tab.value = 'providers'; selected.value = null; selectedId.value = ''; Object.assign(draft, emptyDraft()); headersText.value = '{}'; editing.value = true }
function editSelected() { const item = selected.value; if (!item) return; const config = item.latest_revision?.configuration || item.current_revision?.configuration; Object.assign(draft, { ...emptyDraft(), provider_id: item.provider_id, name: item.name, description: item.description, ...(config || {}), models: (config?.models || [emptyModel()]).map(model => ({ ...model, input_modalities: [...model.input_modalities], tags: [...model.tags] })) }); headersText.value = JSON.stringify(config?.extra_header_refs || {}, null, 2); editing.value = true }
function cancelEdit() { editing.value = false; if (!selected.value && providers.value.length) void selectProvider(providers.value[0].provider_id) }
function addModel() { draft.models.push(emptyModel()) } function removeModel(index: number) { draft.models.splice(index, 1) } function splitList(value: string) { return value.split(',').map(item => item.trim()).filter(Boolean) }
function payload() { const headers = JSON.parse(headersText.value || '{}'); if (!headers || Array.isArray(headers) || typeof headers !== 'object') throw new Error('附加 Header 必须是 JSON 对象'); const pricingKeys = ['input_cost_per_million_tokens', 'output_cost_per_million_tokens', 'cached_input_cost_per_million_tokens', 'cache_creation_input_cost_per_million_tokens'] as const; const models = draft.models.map(model => { const normalized = { ...model } as ModelCatalogItem & Record<string, unknown>; for (const key of pricingKeys) if (String(normalized[key] ?? '').trim() === '') normalized[key] = null; return normalized }); return { ...draft, models, api_key_ref: draft.credential_mode === 'none' ? '' : draft.api_key_ref, extra_header_refs: headers } }
async function saveRevision() { saving.value = true; error.value = ''; try { const value = payload(); const id = draft.provider_id; if (selected.value) await createModelProviderRevision(id, value); else await createModelProvider(value); message.success('Provider Draft 已保存'); selectedId.value = id; editing.value = false; await load() } catch (cause) { error.value = errorText(cause) } finally { saving.value = false } }
async function publishProvider() { if (!selected.value || !publishableRevision.value) return; publishing.value = true; error.value = ''; try { await publishModelProviderRevision(selected.value.provider_id, publishableRevision.value.revision_id); message.success('Provider 已进入 Worker 预热'); await load() } catch (cause) { error.value = errorText(cause) } finally { publishing.value = false } }
async function rollbackProvider() { const rollout = selected.value?.latest_rollout; if (!rollout || !window.confirm(`回滚 Provider 到 ${rollout.previous_revision_id}？`)) return; try { await rollbackConfigurationRollout(rollout.rollout_id); message.success('Provider 回滚已进入 Worker 预热'); await load() } catch (cause) { error.value = errorText(cause) } }
function providerState(item: ModelProviderProfile) { if (item.execution_ready) return '执行就绪'; if (item.latest_rollout && ['rolling_out', 'awaiting_approval'].includes(item.latest_rollout.status)) return 'Worker 预热中'; if (item.current_revision_id) return '已生效，Worker 不完整'; return item.latest_revision?.status === 'draft' ? 'Draft' : '未配置' }
function kindLabel(value: string) { return ({ llm: 'LLM', embedding: 'EMBED', rerank: 'RERANK', transcription: 'ASR', speech: 'TTS', image: 'IMAGE', video: 'VIDEO' } as Record<string, string>)[value] || value.toUpperCase() }
function compactNumber(value: number) { return value >= 1_000_000 ? `${(value / 1_000_000).toFixed(1)}M` : value >= 1000 ? `${Math.round(value / 1000)}K` : String(value) }
function formatDate(value?: string | null) { return value ? new Date(value).toLocaleString('zh-CN') : '—' } function errorText(value: unknown) { return value instanceof Error ? value.message : '操作失败' }
onMounted(load)
</script>

